from itertools import permutations
transforms=lambda r,c: {(r,c),(r,26-c),(26-r,c),(26-r,26-c)}
def predict(inp,order='row',mode='fill'):
 out=[row[:] for row in inp]
 cells=[(r,c) for r in range(27) for c in range(27) if inp[r][c]!=4]
 if order=='rev': cells=cells[::-1]
 elif order=='quadrant':
  # placeholder
  cells=sorted(cells,key=lambda x: (0 if x[0]<13 and x[1]<13 else 1 if x[0]<13 else 2 if x[1]<13 else 3, x[0],x[1]))
 for r,c in cells:
  v=inp[r][c]
  for rr,cc in transforms(r,c):
   if mode=='fill':
    if inp[rr][cc]==4 and out[rr][cc]==4: out[rr][cc]=v
   elif mode=='first':
    if out[rr][cc]==4: out[rr][cc]=v
   elif mode=='overwrite': out[rr][cc]=v
 return out
